preset.frame_eqs_eel:
wave_r = 0.5 + 0.5*sin(1.6*time);
wave_g = 0.5 + 0.5*sin(4.1*time);
wave_b = -1 + (1-wave_r + 1-wave_g);
warp = 2;
wave_x = wave_x + 0.1*sin(1.2*time) + 0.1*sin(0.1*time);
wave_y = wave_y + 0.2*cos(1.4*time) - 0.1*cos(0.4*time);
ob_r = wave_g;
ob_b = wave_r;
ob_g = wave_b;
ib_r = 1-abs(ob_r);
ib_b = 1-abs(ob_b);
ib_g = 1-abs(ob_g);
q1 = wave_r;
q2 = wave_b;
q3 = wave_g;

cog = ocog+0.005*(bass+bass_att+(bass*bass_att)-2);
ocog = below(cog,30000)*cog;
